(function (global) {
    function ensureHooks(target) {
        if (!target) {
            return;
        }
        if (typeof target.on !== "function") {
            target.on = function () { return target; };
        }
        if (typeof target.removeAllListeners !== "function") {
            target.removeAllListeners = function () { return target; };
        }
    }

    function renderPlaceholder(target, layout) {
        if (!target) {
            return;
        }
        ensureHooks(target);
        var title = layout && layout.title ? String(layout.title) : "Plot";
        target.innerHTML = "<div style='display:flex;align-items:center;justify-content:center;height:100%;min-height:220px;border:1px dashed #c4d0df;border-radius:10px;background:#fbfdff;color:#5f7288;font:12px Arial,sans-serif;'>" +
            title.replace(/[&<>\"']/g, function (ch) {
                return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[ch];
            }) +
            " is using the hosted local Plotly compatibility shim.</div>";
    }

    global.Plotly = global.Plotly || {
        react: function (target, traces, layout) {
            renderPlaceholder(target, layout || {});
            return Promise.resolve(target);
        },
        purge: function (target) {
            if (target) {
                target.innerHTML = "";
            }
        },
        newPlot: function (target, traces, layout) {
            return this.react(target, traces, layout);
        },
        version: "2.26.0-shim"
    };
})(window);